{
  "findings": [
    {
      "check_id": "CKV_AZURE_109",
      "title": "Ensure that Virtual Machine Scale Sets use managed disks (OS Disk)",
      "resource": "azurerm_windows_virtual_machine_scale_set.negative4",
      "severity": "HIGH",
      "explanation": "The resource does not define an 'os_disk' block. By default, Azure VMSS may use ephemeral OS disks or unmanaged disks depending on the SKU and configuration, which can lead to data loss upon deallocation/restart if not explicitly configured for persistence with Managed Disks."
    },
    {
      "check_id": "CKV_AZURE_110",
      "title": "Ensure that Virtual Machine Scale Sets use managed disks (Data Disk)",
      "resource": "azurerm_windows_virtual_machine_scale_set.negative4",
      "severity": "MEDIUM",
      "explanation": "No 'storage_data_disk' blocks are defined. While not strictly a security violation if no data is stored, it is best practice to explicitly manage disk configurations to ensure encryption at rest and proper lifecycle management."
    },
    {
      "check_id": "CKV_AZURE_111",
      "title": "Ensure that Virtual Machine Scale Sets have automatic instance repair enabled",
      "resource": "azurerm_windows_virtual_machine_scale_set.negative4",
      "severity": "LOW",
      "explanation": "The 'automatic_instance_repair' block is missing. Without this, unhealthy instances will not be automatically replaced, potentially impacting availability and security posture if compromised instances remain in rotation."
    }
  ],
  "patched_code": "resource \"azurerm_windows_virtual_machine_scale_set\" \"negative4\" {\n  name                 = \"negative4-vmss\"\n  resource_group_name  = azurerm_resource_group.negative4.name\n  location             = azurerm_resource_group.negative4.location\n  sku                  = \"Standard_F2\"\n  computer_name_prefix = \"vm-\"\n\n  encryption_at_host_enabled = true\n\n  os_disk {\n    caching              = \"ReadWrite\"\n    storage_account_type = \"Premium_LRS\"\n  }\n\n  automatic_instance_repair {\n    enabled      = true\n    grace_period = \"PT30M\"\n  }\n}\n",
  "fix_summary": "Added an explicit 'os_disk' block using Premium_LRS managed disks to ensure persistent storage and encryption at rest compliance. Added 'automatic_instance_repair' to improve resilience and maintain security posture by replacing unhealthy instances."
}
